@import "@fontsource-variable/instrument-sans";
@import "@fontsource/ibm-plex-mono/400.css";
@import "@fontsource/ibm-plex-mono/500.css";

/* Light (faithful): white page, warm light grey (#f4f2f0) panels and quiet buttons, warm ink
   (#0c0a08) with a 60% hushed grey, Ramp's acid lime (#e4f222) for the main CTAs, cool
   hairlines (#e4e7ea), near-black (#1a1919) bars and footer. */
:root {
  --background: oklch(1 0 0);
  --foreground: oklch(0.146 0.006 69);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.146 0.006 69);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.146 0.006 69);
  --primary: oklch(0.92 0.201 114);
  --primary-foreground: oklch(0.146 0.006 69);
  --secondary: oklch(0.962 0.003 68);
  --secondary-foreground: oklch(0.146 0.006 69);
  --muted: oklch(0.962 0.003 68);
  --muted-foreground: oklch(0.146 0.006 69 / 60%);
  --accent: oklch(0.93 0.004 68);
  --accent-foreground: oklch(0.146 0.006 69);
  --destructive: oklch(0.6 0.2 28);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0.927 0.005 248);
  --input: oklch(0.854 0.006 60);
  --ring: oklch(0.614 0.13 261);
  --highlight: oklch(0.662 0.182 45);
  --highlight-foreground: oklch(1 0 0);
  --glow: oklch(0.966 0.158 113);
  --chart-1: oklch(0.92 0.201 114);
  --chart-2: oklch(0.614 0.13 261);
  --chart-3: oklch(0.662 0.182 45);
  --chart-4: oklch(0.297 0.036 178);
  --chart-5: oklch(0.527 0.006 49);
  --sidebar: oklch(0.962 0.003 68);
  --sidebar-foreground: oklch(0.146 0.006 69);
  --sidebar-primary: oklch(0.215 0.002 17);
  --sidebar-primary-foreground: oklch(1 0 0);
  --sidebar-accent: oklch(0.93 0.004 68);
  --sidebar-accent-foreground: oklch(0.146 0.006 69);
  --sidebar-border: oklch(0.927 0.005 248);
  --sidebar-ring: oklch(0.614 0.13 261);

  --typeface-body: "Instrument Sans Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Instrument Sans Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: "IBM Plex Mono", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0.75rem;
  --page-width: 90rem;
  --page-gutter: 1rem;
  --section-y: 2.5rem;
}

/* Dark sibling: the footer's near-black (#1a1919) as the page, #262523 panels, warm white
   ink with a 60% hushed grey, the same acid lime. */
.dark {
  --background: oklch(0.215 0.002 17);
  --foreground: oklch(0.985 0.002 90);
  --card: oklch(0.239 0.004 107);
  --card-foreground: oklch(0.985 0.002 90);
  --popover: oklch(0.265 0.004 85);
  --popover-foreground: oklch(0.985 0.002 90);
  --primary: oklch(0.92 0.201 114);
  --primary-foreground: oklch(0.146 0.006 69);
  --secondary: oklch(0.265 0.004 85);
  --secondary-foreground: oklch(0.985 0.002 90);
  --muted: oklch(0.265 0.004 85);
  --muted-foreground: oklch(0.985 0.002 90 / 60%);
  --accent: oklch(0.297 0.004 85);
  --accent-foreground: oklch(0.985 0.002 90);
  --destructive: oklch(0.68 0.19 28);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(1 0 0 / 10%);
  --input: oklch(1 0 0 / 20%);
  --ring: oklch(0.7 0.12 261);
  --highlight: oklch(0.7 0.17 45);
  --highlight-foreground: oklch(0.146 0.006 69);
  --glow: oklch(0.92 0.201 114);
  --chart-1: oklch(0.92 0.201 114);
  --chart-2: oklch(0.7 0.12 261);
  --chart-3: oklch(0.7 0.17 45);
  --chart-4: oklch(0.6 0.06 178);
  --chart-5: oklch(0.7 0.006 49);
  --sidebar: oklch(0.239 0.004 107);
  --sidebar-foreground: oklch(0.985 0.002 90);
  --sidebar-primary: oklch(0.92 0.201 114);
  --sidebar-primary-foreground: oklch(0.146 0.006 69);
  --sidebar-accent: oklch(0.297 0.004 85);
  --sidebar-accent-foreground: oklch(0.985 0.002 90);
  --sidebar-border: oklch(1 0 0 / 10%);
  --sidebar-ring: oklch(0.7 0.12 261);
}
